          } else {
            this.$toast('暂无上次投注数据')
            this.currentChipItem = 1
            return
          }
        } else if (this.currentChipItem === '加倍') {
          this.buyList.forEach(ele => {
            if (item.id === ele.id) {
              ele.buymons += ele.buymons
              // this.mons = ele.buymons
            }
          })
        } else {
          this.buyList.forEach(ele => {
            if (item.id === ele.id) {
              ele.buymons += this.currentChipItem || 0
              // this.mons = ele.buymons
            }
          })
        }
        let currentbuymons = 0
        this.buyList.forEach(ele => {
          if (ele.buymons) {
            currentbuymons += Number(ele.buymons)
          }
