        // if (this.currentIndex === ele.id) {
        ele.buymons = 0
        // }
      })
      this.currentbuymons = 0
      // }
      // let currentbuymons = 0
      // this.buyList.forEach(ele => {
      //   if (ele.buymons) {
      //     currentbuymons += Number(ele.buymons)
      //   }
      // })
      // this.currentbuymons = currentbuymons
    },
    saveApi() {
      if (this.currentbuymons > 0) {
        let buytype = ''
        this.buyList.forEach(item => {
          if (Number(item.buymons) > 0) {
            buytype += item.type + ',' + item.value + ',' + item.buymons + ';'
          }
        })
        this.betLoading = true
        save({ mons: String(this.mons), buytype, gametype: this.type
        }).then(res => {
          this.latestMons = JSON.parse(JSON.stringify(this.buyList))
          this.$store.dispatch('user/getInfo') // 更新余额
          // this.monsDisabled = true
          this.mons = null
          // 要求不清空
          // this.currentChipItem = 1
          this.currentIndex = null
          this.buyList.forEach(item => {
            item.buymons = 0
          })
          this.currentbuymons = 0

          this.$emit('openInfo', res.buyid, res.block)

          this.betLoading = false
        })
          .catch(() => {
            this.betLoading = false
          })
      } else {
        this.$toast('请先选择下注金额再选投注区域')
      }
    },
    goOrderDetail(item) {
      this.$router.push({
        path: '/orderRecord',
        query: {
          type: this.type,
          days: '1'
        }
      })
    },
    goRules(item) {
      this.$router.push({
        path: '/rules',
        query: {
          type: this.type
        }
      })
    }
  }
}
