<template>
  <div id="main" class="mainDiv" />
</template>
<script>
import * as echarts from 'echarts'
export default {
  props: {
    remaintimes: {
      type: Number,
      default: null
    }
  },
  data() {
    return {
      startTime: null,
      timerList: []
    }
  },
  watch: {
    remaintimes: {
      deep: true,
      async handler(newVal) {
        this.startTime = newVal
        this.echartOption()
      }
    }
  },
  created() {
    this.startTime = this.remaintimes
  },
  mounted() {
    this.echartOption()
    // this.bus.$on('remainTimeChange', (val) => {
    //   this.startTime = val
    //   this.echartOption()
    // })
  },
  beforeDestroy() {
    this.timerList.forEach((item, index) => {
      clearInterval(item)
    })
    this.timerList = []
  },
  methods: {
    echartOption() {
      // 检测是否已经存在echarts实例，如果不存在，则不再去初始化
      let myChart = echarts.getInstanceByDom(
        document.getElementById('main')
      )
      // 如果为空 则正常进行渲染 反之 不再进行初始化
      if (myChart == null) {
        myChart = echarts.init(document.getElementById('main'))
      }
      // const chartDom = document.getElementById('main')
      // const myChart = echarts.init(chartDom)
      const option = {
        series: [
          {
            type: 'gauge',
            center: ['50%', '50%'],
            startAngle: 225,
            endAngle: -45,
            min: 0,
            max: 60,
            itemStyle: {
              color: 'rgba(79,94,130,0.4)'
            },
            progress: {
              show: true,
              width: 4
            },
            pointer: {
              show: false
            },
            axisLine: {
              show: false
            },
            axisTick: {
              show: false
            },
            splitLine: {
              show: false
            },
            axisLabel: {
              show: false
            },
            detail: {
              show: false
              // valueAnimation: true,
              // width: '60%',
              // lineHeight: 40,
              // borderRadius: 8,
              // offsetCenter: [0, '-15%'],
              // fontSize: 60,
              // fontWeight: 'bolder',
              // // formatter: '{value} °C',
              // color: 'inherit'
            },
            data: [
              {
                value: 60
              }
            ]
          },
          {
            type: 'gauge',
            center: ['50%', '50%'],
            startAngle: 225,
            endAngle: -45,
            min: 0,
            max: 60,
            itemStyle: {
              color: '#4B73D8'
            },
            progress: {
              show: true,
              width: 4
            },
            pointer: {
              show: false
            },
            axisLine: {
              show: false
            },
            axisTick: {
              show: false
            },
            splitLine: {
              show: false
            },
            axisLabel: {
              show: false
            },
            detail: {
              valueAnimation: true,
              width: '60%',
              lineHeight: 40,
              borderRadius: 8,
              offsetCenter: [0, '10%'],
              fontSize: 23,
              fontWeight: 'bolder',
              // formatter: '{value} °C',
              color: '#fff'
            },
            data: [
              {
                value: this.startTime
              }
            ]
          }

        ]
      }
      let random = this.startTime
      console.log('定时器' + this.timerList)
      this.timerList.forEach((item, index) => {
        clearInterval(item)
      })
      this.timerList = []
      const intervalClock = setInterval(() => {
        if (random > 0) {
          random--
        } else {
          // this.bus.$emit('showResult')
          this.$parent.getBlockData()
          // clearInterval(intervalClock)
          // random = 60
        }
        if (random < 4 && random > 1) {
          this.bus.$emit('openTip')
        }
        myChart.setOption({
          series: [
            {
              data: [
                {
                  value: '60'
                }
              ]
            },
            {
              data: [
                {
                  value: random
                }
              ]
            }
          ]
        })
      }, 1000)
      this.timerList.push(intervalClock)
      option && myChart.setOption(option, true)
    }

  }
}
</script>
<style lang="scss" scoped>
.mainDiv{
  height: 180px;
  width: 180px;
}
</style>
