<template>
  <div class="infoBg-minuXY">
    <top-minute :blockfrom="blockfrom" :blocknext="blocknext" :type="type" />
    <div class="betAreaBg">
      <div class="details-minu">
        <div class="amount">
          <div>{{ $t('hxhash.hx07') }}</div>
          <span>{{ issuebuymons }}</span>
        </div>
        <div class="record-rule">
          <div class="ruleBtn" @click="goOrderDetail()">{{ $t('hxhash.hx08') }}</div>
          <div class="line" />
          <div class="ruleBtn" @click="goRules()">{{ $t('hxhash.hx09') }}</div>
        </div>
      </div>
      <div class="betArea">
        <div class="type">
          <div :class="currentIndex==='1'?'typeBox':'typeBox'" @click="currentIndex='1'">
            <div class="interval">{{ $t('hxhash.hx10') + ' '+boxDataLeft.xhmin1+'-'+boxDataLeft.xhmax1 }}</div>
            <div class="h40" />
            <div class="rate">{{ '1:'+boxDataLeft.odd1 }}</div>
            <div class="totalBet">
              <span>{{$t('hxhash.hx122')}}</span>
              <span :ref="'ani1'">{{ currentIndex==='1'?mons||0:0 }}</span>
            </div>
          </div>
        </div>
        <div class="chips">
          <div v-for="(item,index) in chipList" :key="index" :class="currentChipItem===item.value?'active':''" class="chips-item" style="height:34px" @click="setMons(item.value)">{{ item.label }}</div>
          <input v-model="mons" type="number" :disabled="monsDisabled" :placeholder="$t('hxhash.hx19')" class="chipInput" style="height:34px">
        </div>
        <div class="confirmArea">
          <div class="confirmBtn" style="color:#fff" :class="currentChipItem==='上期'?'activeA':''" @click="currentChipItem = '上期';setLatestMons(latestMons||0)"><van-icon name="replay" />{{ $t('hxhash.hx22') }}</div>
          <div class="confirmBtn" style="color:#fff" :class="currentChipItem==='加倍'?'activeA':''" @click="currentChipItem = '加倍';setLatestMons(mons)">x2 {{ $t('hxhash.hx23') }}</div>
        </div>
        <div class="confirmArea">
          <div class="confirmBtn" @click="mons=null;currentChipItem = null">{{ $t('hxhash.hx21') }}</div>
          <div :class="mons && currentIndex?'confirmBtn active':'confirmBtn'" @click="saveBuy()">{{ $t('hxhash.hx20') }}</div>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
import { getGameInfo, save } from '@/api/game'
import TopMinute from './modules/TopMinute.vue'
export default {
  components: { TopMinute },
  props: {
    type: {
      type: String,
      default() {
        return ''
      }
    },
    opened: {
      type: Boolean,
      default() {
        return false
      }
    }
  },
  data() {
    return {
      currentIndex: '1',
      latestMons: null,
      // chipList: [1, 10, 50, 1000, 10000],
      chipList: [{ label: '1', value: 1 }, { label: '5', value: 5 }, { label: '10', value: 10 }, { label: '50', value: 50 }, { label: '100', value: 100 }, { label: '1k', value: 1000 }],
      boxDataLeft: {
        xhmin1: '',
        xhmin2: '',
        xhmax1: '',
        xhmax2: '',
        odd1: '',
        odd2: ''
      },
      blockfrom: '',
      blocknext: '',
      mons: null,
      monsDisabled: false,
      issuebuymons: 0,
      currentChipItem: null
    }
  },
  watch: {
    opened(val) {
      if (val) {
        this.issuebuymons = 0
      }
    }
  },
  created() {
    getGameInfo({ gametype: this.type
    }).then(res => {
      this.boxDataLeft = res
      this.blockfrom = res.blockfrom
      this.blocknext = res.blocknext
      this.issuebuymons = res.issuebuymons
    })
  },
  mounted() {
    setTimeout(() => {
      window.scrollTo(0, 200)
    })
  },
  methods: {
    setLatestMons(item) {
      if (this.$store.getters.userInfo.mons < item) {
        this.$toast('您的余额不足')
      } else {
        this.mons = Number(this.mons) + item
      }
      if (this.currentIndex) {
        this.$refs['ani' + this.currentIndex].classList.add('num-cahnge')
        setTimeout(() => {
          this.$refs['ani' + this.currentIndex].classList.remove('num-cahnge')
        }, 500)
      }
    },
    setMons(item) {
      this.currentChipItem = item
      if (this.$store.getters.userInfo.mons < item) {
        this.$toast('您的余额不足')
      } else {
        this.mons = Number(this.mons) + item
      }
      if (this.currentIndex) {
        this.$refs['ani' + this.currentIndex].classList.add('num-cahnge')
        setTimeout(() => {
          this.$refs['ani' + this.currentIndex].classList.remove('num-cahnge')
        }, 500)
      }
    },
    saveBuy() {
      if (this.mons && this.currentIndex) {
        const min = this.currentIndex === '1' ? this.boxDataLeft.xhmin1 : this.boxDataLeft.xhmin2
        const max = this.currentIndex === '1' ? this.boxDataLeft.xhmax1 : this.boxDataLeft.xhmax2
        if (this.mons > Number(min) - 1 && this.mons < Number(max) + 1) {
          this.saveApi()
        } else {
          this.$toast('超出允许限红范围，请重新投注')
        }
      } else if (!this.mons) {
        this.$toast('请选择或输入金额')
      } else if (!this.currentIndex) {
        this.$toast('请选择下注区域')
      }
    },
    saveApi() {
      save({ mons: String(this.mons), buytype: this.currentIndex, gametype: this.type
      }).then(res => {
        this.latestMons = this.mons
        this.$toast.success(this.$t('hxhash.hx30'))
        this.$store.dispatch('user/getInfo') // 更新余额
        // this.monsDisabled = true
        this.mons = null
        this.currentChipItem = null
        this.issuebuymons = res.issuebuymons
        // this.$emit('openInfo', res.buyid , res.block)
      })
    },
    goOrderDetail(item) {
      this.$router.push({
        path: '/orderRecord',
        query: {
          type: this.type,
          days: '1'
        }
      })
    },
    goRules(item) {
      this.$router.push({
        path: '/rules',
        query: {
          type: this.type
        }
      })
    }
  }
}
</script>
