<script>
import scratchCard from 'lzy-scratch-card'
import hxyx_107 from '@/assets/portal/poker/back.png'
import pic1 from '@/assets/portal/poker/1.png'
import pic2 from '@/assets/portal/poker/2.png'
import pic3 from '@/assets/portal/poker/3.png'
import pic4 from '@/assets/portal/poker/4.png'
import pic5 from '@/assets/portal/poker/5.png'
import pic6 from '@/assets/portal/poker/6.png'
import pic7 from '@/assets/portal/poker/7.png'
import pic8 from '@/assets/portal/poker/8.png'
import pic9 from '@/assets/portal/poker/9.png'
import pic0 from '@/assets/portal/poker/0.png'
import { getIssueDetail } from '@/api/game'
export default {
  components: {
    scratchCard
  },
  props: {
    info: {
      type: Object,
      default() {
        return {
        }
      }
    }
  },
  data() {
    return {
      picList: [pic0, pic1, pic2, pic3, pic4, pic5, pic6, pic7, pic8, pic9],
      modeType: 'zjkj',
      modeTypeFlag: 'zjkj',
      isShow: false,
      isEnd: true,
      pic: hxyx_107,
      showRecentList: false,
      recentRecordlist: []
    }
  },
  computed: {
    result() {
      return `<img style="height:299px;width:202px;" src=${this.picList[Number(this.info.openname)]} />`
    }
  },
  mounted() {
    this.modeType = localStorage.getItem('modeType') || 'zjkj'
    this.modeTypeFlag = localStorage.getItem('modeType') || 'zjkj'
    if (this.modeType === 'sdkj') {
      this.isShow = false
      this.isEnd = false
    } else if (this.modeType === 'zjkj') {
      this.isShow = true
      this.isEnd = true
    } else {
      this.isShow = false
      this.isEnd = false
    }
  },
  methods: {
    getList() {
      this.showRecentList = !this.showRecentList
      if (this.showRecentList) {
        // if (this.type === 'gameMinuZH') {
        const params = { gametype: this.info.gametype, block: this.info.block }
        // } else {
        //   params = { gametype: this.type }
        // }
        getIssueDetail(params).then(res => {
          this.recentRecordlist = res.datalist
        })
      }
    },
    setType(val) {
      this.modeTypeFlag = val
      localStorage.setItem('modeType', val)
      if (val === 'zjkj') {
        this.isEnd = true
        this.isShow = true
      }
    },
    clearCallbackUp() {
      setTimeout(() => {
        this.isEnd = true
        this.isShow = true
      }, 2000)
      // this.isShow = true
    },
    doCopy(val) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success(this.$t('yqhy.yqhy10'))
        },
        (e) => {
          // fail
          console.log(e)
        }
      )
    },
    goVerify() {
      this.$router.push({
        path: '/verifyFairness'
      })
    },
    onClick(val) {
      // window.open('https://tronscan.org/#/block/' + this.info.block)
      this.$router.push({
        path: '/verifyIndex',
        query: {
          block: val,
          blockurl: ''
        }
      })
    }
  }
}
</script>
