      default() {
        return {}
      }
    }
  },
  data() {
    return {
    }
  },
  mounted() {
  },
  methods: {
    doCopy(val) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success(this.$t('yqhy.yqhy10'))
        },
        (e) => {
          // fail
          console.log(e)
        }
      )
    },
    goVerify() {
      this.$router.push({
        path: '/verifyFairness'
      })
    },
    onClick(val) {
      this.$router.push({
        path: '/verifyIndex',
        query: {
          block: val,
          blockurl: ''
        }
      })
      //   window.location.href = 'https://tronscan.org/#/block/' + this.info.label
