      </div>
      <div class="periodNum">
        <div class="last qishu">
          <div class="last-icon" />
          <div class="u-count-num">{{ blockfrom }}</div>
          <!-- <div class="verifyBtn" @click="goVerify(blockfrom)">验证</div> -->
        </div>
        <div class="time">
          <time-interval v-if="remaintimes||remaintimes===0" :remaintimes="remaintimes" />
        </div>
        <div class="next qishu">
          <div class="next-icon" />
          <div class="u-count-num">{{ blocknext }}</div>
        </div>
      </div>
      <div class="periodInfo">
