          <div class="last-num-icon">
            <div class="verifyBtn" @click="goVerify(blockfrom)">{{$t('hxhash.hx121')}}</div>
          </div>
          <div class="">
            <div>...</div>
            <div>{{ hashValueArr&&hashValueArr[0] }}
              <span style="color: #7FADFF">{{ hashValueArr&&hashValueArr[1] }}</span>{{ hashValueArr&&hashValueArr[2] }}
            </div>
            <span>（{{ lastopenname }}）</span>
          </div>
        </div>
