<script>
import TimeInterval from './TimeInterval.vue'
import { getCurrentBlockMinu, getTrend } from '@/api/game'

export default {
  components: { TimeInterval },
  props: {
    type: {
      type: String,
      default() {
        return ''
      }
    }
  },
  data() {
    return {
      currentIndex: null,
      showRecentList: false,
      recentRecordlist: [],
      blockfrom: null,
      blocknext: null,
      remaintimes: null,
      lastopenname: '',
      opennum: '',
      lastblockhash: '',
      hashValueArr: []
    }
  },
  created() {
    this.getBlockData()
    this.$socket.open()
    // 订阅事件，testCall 是与后端约定好的名称
    const gametype = this.type.includes('Bull') ? 'Bull' : this.type.includes('Dice') ? 'Dice' + this.type.slice(this.type.length - 2, this.type.length) : this.type.slice(this.type.length - 2, this.type.length)
    this.sockets.subscribe('getblockOne' + gametype, (res) => {
      const data = JSON.parse(res)
      this.blocknext = Number(data.blocknext)
      this.blockfrom = Number(data.blockfrom)
      // this.remaintimes = 60
      // this.bus.$emit('remainTimeChange', 60)
      this.lastopenname = data.lastopenname
      this.opennum = data.opennum
      this.lastblockhash = data.lastblockhash
      this.hashValueArr = this.handleHash(data.lastblockhash)
      this.$parent.issuebuymons = 0
      // this.getBlockData()
    })
  },
  mounted() {
    document.addEventListener('visibilitychange',this.visibleMethod)
  },
  beforeDestroy() {
    // if (this.interval) {
    //   clearInterval(this.interval)
    // }
    const gametype = this.type.includes('Bull') ? 'Bull' : this.type.includes('Dice') ? 'Dice' + this.type.slice(this.type.length - 2, this.type.length) : this.type.slice(this.type.length - 2, this.type.length)
    this.sockets.unsubscribe('getblockOne' + gametype)
    this.$socket.close()
    document.removeEventListener('visibilitychange',this.visibleMethod)
  },
  methods: {
    visibleMethod(){
      if (document.visibilityState === 'visible') {
        this.getBlockData()
      } else {
        // backgroundMusic.pause()
      }
    },
    searchMore() {
      this.$router.push({
        path: '/searchMoreInfo',
        query: {
          // t: +new Date()
        }
      })
    },
    getList() {
      this.showRecentList = !this.showRecentList
      if (this.showRecentList) {
        let params
        if (this.type === 'gameMinuZH') {
          params = { gametype: this.type, index: '2' }
        } else {
          params = { gametype: this.type }
        }
        getTrend(params).then(res => {
          this.recentRecordlist = res.datalist.reverse().map(item => {
            return {
              block: item.block,
              value: this.handleHashList(item.blockhash),
              result: item.typename,
              opennum: item.opennum
            }
          })
        })
      }
    },
    goVerify(val) {
      // window.open('https://tronscan.org/#/block/' + val)
      this.$router.push({
        path: '/verifyIndex',
        query: {
          block: val,
          blockurl: ''
        }
      })
    },
    getApi() {
      const date = new Date()
      const hour = date.getHours() // 时
      const minutes = date.getMinutes() // 分
      const seconds = date.getSeconds() // 秒
      if ((hour === 2 || hour === 8 || hour === 14 || hour === 20) && minutes === 0 && (seconds > 0 && seconds < 10)) {
        return true
      } else {
        return false
      }
    },
    getBlockData() {
      getCurrentBlockMinu({ gametype: this.type }).then(res => {
        this.blocknext = Number(res.blocknext)
        this.blockfrom = Number(res.blockfrom)
        this.remaintimes = Number(res.remaintimes)
        this.lastopenname = res.lastopenname
        this.opennum = res.opennum
        this.lastblockhash = res.lastblockhash
        this.hashValueArr = this.handleHash(res.lastblockhash)
        // setTimeout(() => {
        //   this.blockfrom += 20
        //   this.blocknext += 20
        //   // this.remaintimes = 60
        //   this.interval = setInterval(() => {
        //     if (this.getApi()) {
        //       clearInterval(this.interval)
        //       this.getBlockData()
        //     } else {
        //       this.blockfrom += 20
        //       this.blocknext += 20
        //       // this.remaintimes = 60
        //     }
        //   }, 20 * 3000)
        // }, res.remaintimes * 1000)
      })
    },
    handleHash(val) {
      if (this.type.includes('Bull') || this.type.includes('ZX')) {
        const valTemp = val.slice(val.length - 5, val.length)
        return ['', valTemp.slice(valTemp.length - 5, valTemp.length), '']
      } else if (this.type.includes('XY')) { // 后2位高亮
        const valTemp = val.slice(val.length - 5, val.length)
        return [valTemp.slice(valTemp.length - 5, valTemp.length - 2), valTemp.slice(valTemp.length - 2, valTemp.length), '']
      } else {
        val = val.slice(val.length - 6, val.length)
        const arr = val.split('')
        const valueArr = []
        for (let i = arr.length - 1; i > 0; i--) {
          if (!isNaN(Number(arr[i]))) {
            valueArr.push(val.slice(0, i), arr[i], val.slice(i + 1, val.length))
            return valueArr
          }
        }
      }
    },
    handleHashList(val) { // 列表处理
      if (this.type.includes('Bull') || this.type.includes('ZX')) {
        const valTemp = val.slice(val.length - 9, val.length)
        return [val.slice(0, 2) + '...' + valTemp.slice(0, valTemp.length - 5), valTemp.slice(valTemp.length - 5, valTemp.length), '']
      } else if (this.type.includes('XY')) { // 后2位高亮
        const valTemp = val.slice(val.length - 9, val.length)
        return [val.slice(0, 2) + '...' + valTemp.slice(0, valTemp.length - 2), valTemp.slice(valTemp.length - 2, valTemp.length), '']
      } else {
        const valTemp = val.slice(val.length - 9, val.length)
        const arr = valTemp.split('')
        const valueArr = []
        for (let i = arr.length - 1; i > 0; i--) {
          if (!isNaN(Number(arr[i]))) {
            valueArr.push(val.slice(0, 2) + '...' + valTemp.slice(0, i), arr[i], valTemp.slice(i + 1, valTemp.length))
            return valueArr
          }
        }
      }
    }
  },
  sockets: {
    // 链接成功
    connect(data) {
      console.log(data)
    },
    // 发送消息
    toServer(data) {
      this.$socket.emit('toServer', data)
    },
    // 接收消息
    toClient(data) {
      this.msgList.push(data)
    },
    // 断开链接回调
    disconnect() {
      console.log('disconnect：', '已经断开 socket 链接')
    },
    // 重新连接
    reconnect() {
    // 自动执行，直到链接成功
      this.$socket.emit('connect')
    }
  }
}
</script>
