<template>
  <div>
    <div class="block-hash">
      <div style="display:flex">
        <div class="hash">
          <div class="title">{{ $t('hxhash.hx04') }}</div>
          <div class="block-num">{{ blockfrom }}</div>
        </div>
        <div class="line" />
        <div class="hash">
          <div class="title">{{ $t('hxhash.hx05') }}</div>
          <div class="block-num">{{ blocknext }}</div>
        </div>
      </div>
      <div class="more-info" @click="searchMore()">
        {{ $t('hxhash.hx06') }}
        <van-icon name="arrow" />
      </div>
    </div>

  </div>

</template>
<script>
import { getCurrentBlockNormal } from '@/api/game'
export default {
  data() {
    return {
      blockfrom: null,
      blocknext: null
    }
  },
  // props: {
  //   blockfrom: {
  //     type: String,
  //     default: ''
  //   },
  //   blocknext: {
  //     type: String,
  //     default: ''
  //   }
  // },
  created() {
    this.getBlockData()
    this.$socket.open()
    // 订阅事件，testCall 是与后端约定好的名称
    this.sockets.subscribe('blockinfo', (res) => {
      const data = JSON.parse(res)
      this.blockfrom = data.blockfrom
      this.blocknext = data.blocknext
    })
  },

  beforeDestroy() {
    // if (this.interval) {
    //   clearInterval(this.interval)
    // }
    this.sockets.unsubscribe('blockinfo')
    this.$socket.close()
  },
  sockets: {
    // 链接成功
    connect(data) {
      console.log(data)
    },
    // 发送消息
    toServer(data) {
      this.$socket.emit('toServer', data)
    },
    // 接收消息
    toClient(data) {
      this.msgList.push(data)
    },
    // 断开链接回调
    disconnect() {
      console.log('disconnect：', '已经断开 socket 链接')
    },
    // 重新连接
    reconnect() {
    // 自动执行，直到链接成功
      this.$socket.emit('connect')
    }
  },
  methods: {
    searchMore() {
      this.$router.push({
        path: '/searchMoreInfo',
        query: {
          // t: +new Date()
        }
      })
    },
    // getApi() {
    //   const date = new Date()
    //   const hour = date.getHours() // 时
    //   const minutes = date.getMinutes() // 分
    //   const seconds = date.getSeconds() // 秒
    //   if ((hour === 2 || hour === 8 || hour === 14 || hour === 20) && minutes === 0 && (seconds > 0 && seconds < 10)) {
    //     return true
    //   } else {
    //     return false
    //   }
    // },
    getBlockData() {
      getCurrentBlockNormal({ gametype: '11' }).then(res => {
        this.blocknext = Number(res.blocknext)
        this.blockfrom = Number(res.blockfrom)
        // this.interval = setInterval(() => {
        //   if (this.getApi()) {
        //     clearInterval(this.interval)
        //     this.getBlockData()
        //   } else {
        //     this.blockfrom++
        //     this.blocknext++
        //   }
        // }, 3000)
      })
    }
  }
}
</script>
<style lang="scss" scoped>

.block-hash {
    height: 90px;
    display: block;
    align-items: center;
    .hash {
        width: 50%;
        display: block;
        align-items: flex-end;
        .title {
            font-size: 24px;
            // width: 114px;
            color: #7582a2;
            margin-right: 8px;
            flex-grow: 0;
            text-align: center;
        }
        .block-num {
            text-align: left;
            flex-grow: 1;
            font-size: 36px;
            color: #fff;
            text-align: center;
            margin-top: 6px;
        }
    }
    .line {
        height: 40px;
        width: 1px;
        background: #4f5e82;
    }
    .more-info{
          display: flex;
          font-size: 20px;
          color: #7582a2;
          // justify-content: end;
          float: right;
          margin: 10px 0;
    }
}
</style>
